PHOTOS = [
'data:image/webp;base64,',
'data:image/webp;base64,',
'data:image/webp;base64,',
'data:image/webp;base64,',
'data:image/webp;base64,'
]

def replace_work_photos(html):
    for i, photo in enumerate(PHOTOS, 1):
        html = html.replace(f'data:image/jpeg;base64,...(photo {i})...', photo)
    return html
